// r7-merge: per-workload dispatch over 4 unchanged kernels (loop/merge.py).
//   r5-a-e2-ringk2: 8,320,32,32 4,96,56,56 32,768,7,7; r6-d-e2-epi-fix: 8,768,7,7 16,768,7,7 16,384,14,14 8,384,14,14 2,768,7,7; r7-d-e2-smallc: 2,96,56,56 1,160,449,7 1,96,56,56 4,192,28,28 1,192,28,28 8,192,28,28 (+ any other shape); r7-g-e1-fusedp1-mma: 64,96,112,112 32,128,64,64
#include <torch/extension.h>
#include <cstdint>

namespace lf_r5_a_e2_ringk2 { void merge_entry_(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2, double eps, double ln_eps, torch::Tensor out); }
namespace lf_r6_d_e2_epi_fix { void merge_entry_(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2, double eps, double ln_eps, torch::Tensor out); }
namespace lf_r7_d_e2_smallc { void merge_entry_(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2, double eps, double ln_eps, torch::Tensor out); }
namespace lf_r7_g_e1_fusedp1_mma { void merge_entry_(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2, double eps, double ln_eps, torch::Tensor out); }

void run(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1, torch::Tensor b1, torch::Tensor gw, torch::Tensor gb, torch::Tensor w2, torch::Tensor b2, double eps, double ln_eps, torch::Tensor out) {
  const int64_t batch_size = x.size(0);
  const int64_t dim = x.size(1);
  const int64_t height = x.size(2);
  const int64_t width = x.size(3);
  if ((batch_size == 8 && dim == 320 && height == 32 && width == 32) || (batch_size == 4 && dim == 96 && height == 56 && width == 56) || (batch_size == 32 && dim == 768 && height == 7 && width == 7)) {
    lf_r5_a_e2_ringk2::merge_entry_(x, dww, dwb, lnw, lnb, w1, b1, gw, gb, w2, b2, eps, ln_eps, out);
    return;
  }
  if ((batch_size == 8 && dim == 768 && height == 7 && width == 7) || (batch_size == 16 && dim == 768 && height == 7 && width == 7) || (batch_size == 16 && dim == 384 && height == 14 && width == 14) || (batch_size == 8 && dim == 384 && height == 14 && width == 14) || (batch_size == 2 && dim == 768 && height == 7 && width == 7)) {
    lf_r6_d_e2_epi_fix::merge_entry_(x, dww, dwb, lnw, lnb, w1, b1, gw, gb, w2, b2, eps, ln_eps, out);
    return;
  }
  if ((batch_size == 64 && dim == 96 && height == 112 && width == 112) || (batch_size == 32 && dim == 128 && height == 64 && width == 64)) {
    lf_r7_g_e1_fusedp1_mma::merge_entry_(x, dww, dwb, lnw, lnb, w1, b1, gw, gb, w2, b2, eps, ln_eps, out);
    return;
  }
  lf_r7_d_e2_smallc::merge_entry_(x, dww, dwb, lnw, lnb, w1, b1, gw, gb, w2, b2, eps, ln_eps, out);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "r7-merge (per-workload merge)"); }

